class RandomizedSet {
    vector<int> items;
    unordered_map<int, int> index;

public:
    bool insert(int val) {
        if (index.count(val)) {
            return false;
        }
        index[val] = items.size();
        items.push_back(val);
        return true;
    }

    bool remove(int val) {
        auto it = index.find(val);
        if (it == index.end()) {
            return false;
        }
        int i = it->second, last = items.back();
        items[i] = last;
        index[last] = i;
        items.pop_back();
        index.erase(val);
        return true;
    }

    int getRandom() {
        return items[rand() % items.size()];
    }
};

