        checkIns.erase(id);
        auto& r = routes[{start, station}];
        r.first += t - t0;
        r.second++;
    }

    double getAverageTime(string startStation, string endStation) {
        auto& r = routes[{startStation, endStation}];
        return r.first / r.second;
    }
