class Twitter {
    int time = 0;
    unordered_map<int, vector<pair<int, int>>> tweets;
    unordered_map<int, unordered_set<int>> follows;

public:
    void postTweet(int userId, int tweetId) {
        tweets[userId].push_back({time++, tweetId});
    }

    vector<int> getNewsFeed(int userId) {
        priority_queue<array<int, 4>> pq;  // {time, tweetId, user, index}
        unordered_set<int> users = follows[userId];
        users.insert(userId);
        for (int u : users) {
            auto& list = tweets[u];
            if (!list.empty()) pq.push({list.back().first, list.back().second, u, (int)list.size() - 1});
        }
        vector<int> feed;
        while (!pq.empty() && feed.size() < 10) {
            auto [t, id, u, i] = pq.top(); pq.pop();
            feed.push_back(id);
            if (i > 0) {
                auto& prev = tweets[u][i - 1];
                pq.push({prev.first, prev.second, u, i - 1});
            }
        }
        return feed;
    }

    void follow(int followerId, int followeeId) {
        if (followerId != followeeId) follows[followerId].insert(followeeId);
    }

    void unfollow(int followerId, int followeeId) {
        follows[followerId].erase(followeeId);
    }
};

